  ('b_a1701', '["책갈피","티셔츠","노트커버","포스터","오브제","그래픽 티셔츠","아크릴 키링","레더 북마크","양초","문장수집 책갈피","교보 키캡 키링","열전사 스티커팩","북 티셔츠","표지석 캔들","반다나"]'::jsonb, '["general","lit","science","humanities"]'::jsonb, '교보문고 오리지널 책갈피·티셔츠 등 굿즈', '굿즈는 현장 판매만 진행, 가격은 현장 공개', 'https://instagram.com/kyobobook_online', '[]'::jsonb, null, '{}'::jsonb, '["티키타카 — 45년 베스트셀러 아카이브","교보생명 서재에 문장 기록"]'::jsonb, '["[사인회] 6/24 14:00 김연수 · 6/26 14:00 송길영 · 6/27 13:00 정영한"]'::jsonb, '[]'::jsonb, '[]'::jsonb, null),
