-- 0023: booth_enrichment 데이터 동기화 — mock enrichment JSON(부스내용·굿즈·사인회
-- + 근거 카드 저작 필드)을 prod 테이블에 멱등 UPSERT. 0021에서 추가한 컬럼(things_to_do·
-- timing·recommendation_reasons 등)에 실제 값을 채운다. indiflow 도서전 가이드 주입 포함.
-- 컬럼은 0013/0021에 이미 존재 — 여기서는 값만 채운다. 재적용 안전(on conflict do update).

on conflict (booth_id) do update set
  goods_keywords = excluded.goods_keywords,
  theme_tags = excluded.theme_tags,
  summary = excluded.summary,
  tips = excluded.tips,
  source_url = excluded.source_url,
  value_tags = excluded.value_tags,
  roam_interpretation = excluded.roam_interpretation,
  recommendation_reasons = excluded.recommendation_reasons,
  things_to_do = excluded.things_to_do,
  timing = excluded.timing,
  memory_hooks = excluded.memory_hooks,
  conversation_prompts = excluded.conversation_prompts,
  confidence = excluded.confidence,
  updated_at = now();
